package io.github.leetcode.strings;

public class ConsecutiveCharacters {

    public int maxPower(String s) {
        int n = s.length();
        int power = 1;

        for (int i = 1; i < n; i++) {
            int temp = 1;
            while (i < n && s.charAt(i) == s.charAt(i - 1)) {
                temp++;
                i++;
            }
            power = Math.max(power, temp);
        }

        return power;
    }

}

class Solution {
    public int maxPower(String s) {
        int count = 0;
        int maxCount = 0;
        char previous = ' ';
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == previous) {
                // if same as previous one, increase the count
                count++;
            } else {
                // else, reset the count
                count = 1;
                previous = c;
            }
            maxCount = Math.max(maxCount, count);
        }
        return maxCount;
    }
}

class Solution:
    def maxPower(self, s: str) -> int:
        count = 0
        max_count = 0
        previous = None
        for c in s:
            if c == previous:
                # if same as previous one, increase the count
                count += 1
            else:
                # else, reset the count
                previous = c
                count = 1
            max_count = max(max_count, count)
        return max_count
